CREATE TABLE public.verification_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, provider text NOT NULL DEFAULT 'veriff' CHECK(provider='veriff'), provider_session_id text UNIQUE, status text NOT NULL DEFAULT 'created' CHECK(status IN('created','pending','approved','declined','resubmission_requested','expired','abandoned','review')), verified_birth_date date, decision_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.verification_sessions TO authenticated; GRANT ALL ON public.verification_sessions TO service_role;
ALTER TABLE public.verification_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY verification_session_owner ON public.verification_sessions FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE INDEX verification_sessions_owner ON public.verification_sessions(user_id,created_at DESC);
CREATE OR REPLACE FUNCTION public.is_verified(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.account_details d WHERE d.user_id=_user_id AND d.birth_date <= (CURRENT_DATE-INTERVAL '18 years')::date AND (COALESCE((SELECT status='approved' FROM public.identity_submissions WHERE user_id=_user_id ORDER BY submitted_at DESC,id DESC LIMIT 1),false) OR EXISTS(SELECT 1 FROM public.verification_sessions v WHERE v.user_id=_user_id AND v.status='approved' AND v.verified_birth_date=d.birth_date))) $$;
REVOKE ALL ON FUNCTION public.is_verified(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_verified(uuid) TO authenticated;